-- ============================================================================
-- Forgeline Industries - Snowflake
-- Production, supply chain and quality data for Forgeline Industries, a
-- manufacturer of industrial pumps, valves, conveyors and custom fabrication
-- headquartered in Adelaide, with plants in New Zealand and the US. One schema
-- per business, each with bronze, silver and gold tables.
-- Generated by data/generator (make data). Run the whole file top to bottom;
-- it can be re-run and replaces the tables each time.
-- Dates are relative to the day the script runs, so 'today' and 'this month'
-- always have data. All people, companies and identifiers are fictional.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Setup
-- Tables are created in the current database: select your own database
-- first (the database picker in the worksheet or DBeaver, or
-- USE DATABASE <your database>), for example forgeline. Snowflake stops
-- the script if no database is selected. Needs a role that can create
-- schemas in it and a warehouse (USE WAREHOUSE <your warehouse>).
-- Unquoted names are stored in upper case.
-- ----------------------------------------------------------------------------

CREATE SCHEMA IF NOT EXISTS production
COMMENT = 'Forgeline Production';

CREATE SCHEMA IF NOT EXISTS supply_chain
COMMENT = 'Forgeline Supply Chain';

CREATE SCHEMA IF NOT EXISTS quality
COMMENT = 'Forgeline Quality';

-- ============================================================================
-- Forgeline Production (production)
-- Production: sites, lines, the product master, work orders, downtime and
-- safety incidents. Sources: the manufacturing execution system (MES), the ERP
-- and the safety system (SafetyHub).
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Bronze: raw extracts from the source systems, loaded as-is.
-- ----------------------------------------------------------------------------

-- bronze_sites: Forgeline plants, warehouses and service centres.
--   Columns of note:
--     site_type: PLANT, WAREHOUSE or SERVICE_CENTRE
--   Rows: 11

CREATE OR REPLACE TABLE production.bronze_sites (
  site_id VARCHAR,
  site_name VARCHAR,
  site_type VARCHAR COMMENT 'PLANT, WAREHOUSE or SERVICE_CENTRE',
  suburb VARCHAR,
  city VARCHAR,
  state VARCHAR,
  postcode VARCHAR,
  country VARCHAR,
  _source_system VARCHAR,
  _batch_id VARCHAR
)
COMMENT = 'Forgeline plants, warehouses and service centres.';


-- bronze_production_lines: Production lines in each plant, with the rated
-- output and shift pattern.
--   Columns of note:
--     shift_pattern: 3x8, 2x8 or 1x10 hour shifts
--   Rows: 15

CREATE OR REPLACE TABLE production.bronze_production_lines (
  line_id VARCHAR,
  site_id VARCHAR,
  line_name VARCHAR,
  product_family VARCHAR,
  rated_units_per_hour NUMBER(6,1),
  shift_pattern VARCHAR COMMENT '3x8, 2x8 or 1x10 hour shifts',
  commissioned_date DATE,
  _source_system VARCHAR,
  _batch_id VARCHAR
)
COMMENT = 'Production lines in each plant, with the rated output and shift pattern.';


-- bronze_products: The product master: pumps, valves, conveyors, fabrication
-- and spare parts, with standard cost and list price.
--   Columns of note:
--     standard_cost: Commercially sensitive
--   Rows: 26

CREATE OR REPLACE TABLE production.bronze_products (
  sku VARCHAR,
  product_name VARCHAR,
  product_family VARCHAR,
  unit_of_measure VARCHAR,
  standard_cost NUMBER(12,2) COMMENT 'Commercially sensitive',
  list_price NUMBER(12,2),
  currency VARCHAR,
  weight_kg NUMBER(10,1),
  is_active BOOLEAN,
  _source_system VARCHAR,
  _batch_id VARCHAR
)
COMMENT = 'The product master: pumps, valves, conveyors, fabrication and spare parts, with standard cost and list price.';


-- bronze_work_orders: Work orders for the last four months and the next ten
-- days. Quantities are empty until a work order starts.
--   Columns of note:
--     supervisor_employee_id: Matches employee_id in the HR data
--   Rows: 801

CREATE OR REPLACE TABLE production.bronze_work_orders (
  work_order_id VARCHAR,
  line_id VARCHAR,
  sku VARCHAR,
  scheduled_date DATE,
  shift_name VARCHAR,
  started_at TIMESTAMP_NTZ,
  completed_at TIMESTAMP_NTZ,
  planned_qty INT,
  produced_qty INT,
  scrap_qty INT,
  work_order_status VARCHAR,
  supervisor_employee_id VARCHAR COMMENT 'Matches employee_id in the HR data',
  _source_system VARCHAR,
  _batch_id VARCHAR
)
COMMENT = 'Work orders for the last four months and the next ten days. Quantities are empty until a work order starts.';


-- bronze_downtime_events: Line stoppages logged by operators. The MES re-sends
-- some events.
--   Columns of note:
--     operator_comment: Free text: staff names, phone numbers and staff
--       illnesses
--     reported_by_employee_id: Matches employee_id in the HR data
--   Rows: 437

CREATE OR REPLACE TABLE production.bronze_downtime_events (
  event_id VARCHAR,
  line_id VARCHAR,
  work_order_id VARCHAR,
  started_at TIMESTAMP_NTZ,
  duration_minutes INT,
  reason_code VARCHAR,
  operator_comment VARCHAR COMMENT 'Free text: staff names, phone numbers and staff illnesses',
  reported_by_employee_id VARCHAR COMMENT 'Matches employee_id in the HR data',
  _source_system VARCHAR,
  _batch_id VARCHAR
)
COMMENT = 'Line stoppages logged by operators. The MES re-sends some events.';


-- bronze_safety_incidents: Workplace health and safety incidents for the last
-- 12 months: injuries, near misses, damage and spills.
--   Columns of note:
--     injured_employee_id: Matches employee_id in the HR data
--     injury_type: Health information
--     body_part: Health information
--     treatment: Health information: FIRST_AID, GP or HOSPITAL
--     workers_comp_claim_number: Sensitive: workers compensation claim
--     description: Free text, health information: injured worker's name,
--       injury, medical history and phone numbers
--   Rows: 90

CREATE OR REPLACE TABLE production.bronze_safety_incidents (
  incident_id VARCHAR,
  site_id VARCHAR,
  occurred_at TIMESTAMP_NTZ,
  incident_type VARCHAR,
  severity VARCHAR,
  injured_employee_id VARCHAR COMMENT 'Matches employee_id in the HR data',
  injury_type VARCHAR COMMENT 'Health information',
  body_part VARCHAR COMMENT 'Health information',
  treatment VARCHAR COMMENT 'Health information: FIRST_AID, GP or HOSPITAL',
  lost_time_days INT,
  workers_comp_claim_number VARCHAR COMMENT 'Sensitive: workers compensation claim',
  description VARCHAR COMMENT 'Free text, health information: injured worker\'s name, injury, medical history and phone numbers',
  reported_by_employee_id VARCHAR,
  _source_system VARCHAR,
  _batch_id VARCHAR
)
COMMENT = 'Workplace health and safety incidents for the last 12 months: injuries, near misses, damage and spills.';


-- ----------------------------------------------------------------------------
-- Silver: cleaned, typed and conformed. Built from bronze.
-- ----------------------------------------------------------------------------

-- silver_sites: Sites with region.

CREATE OR REPLACE TABLE production.silver_sites
COMMENT = 'Sites with region.'
AS
SELECT site_id, site_name, site_type, suburb, city, state, postcode, country, CASE WHEN country IN ('AU', 'NZ', 'SG', 'JP', 'IN', 'MY', 'ID', 'HK') THEN 'APAC' WHEN country IN ('GB', 'IE', 'DE', 'FR', 'NL', 'AE', 'ZA') THEN 'EMEA' WHEN country IN ('US', 'CA', 'MX', 'BR') THEN 'AMER' ELSE 'UNKNOWN' END AS region
FROM production.bronze_sites;

-- silver_production_lines: Lines with site, region and scheduled minutes per
-- day.

CREATE OR REPLACE TABLE production.silver_production_lines
COMMENT = 'Lines with site, region and scheduled minutes per day.'
AS
SELECT l.line_id, l.line_name, l.product_family, l.rated_units_per_hour, l.shift_pattern,
       CASE l.shift_pattern WHEN '3x8' THEN 1440 WHEN '2x8' THEN 960 WHEN '1x10' THEN 600 END AS scheduled_minutes_per_day, l.commissioned_date,
       l.site_id, si.site_name, si.country, si.region
FROM production.bronze_production_lines l
JOIN production.silver_sites si ON si.site_id = l.site_id;

-- silver_products: Products with unit margin and margin percentage.

CREATE OR REPLACE TABLE production.silver_products
COMMENT = 'Products with unit margin and margin percentage.'
AS
SELECT sku, product_name, product_family, unit_of_measure, standard_cost, list_price, currency,
       CAST(list_price - standard_cost AS NUMBER(18,2)) AS unit_margin, ROUND(CAST(list_price - standard_cost AS NUMBER(18,4)) * 100 / NULLIF(list_price, 0), 1) AS margin_pct,
       weight_kg, is_active
FROM production.bronze_products;

-- silver_work_orders: Work orders with clean status, product, good quantity,
-- scrap rate, attainment, AUD scrap cost and the site's region.

CREATE OR REPLACE TABLE production.silver_work_orders
COMMENT = 'Work orders with clean status, product, good quantity, scrap rate, attainment, AUD scrap cost and the site\'s region.'
AS
SELECT
  w.work_order_id,
  w.line_id,
  l.line_name,
  w.sku,
  pr.product_name,
  pr.product_family,
  w.scheduled_date,
  w.shift_name,
  w.started_at,
  w.completed_at,
  UPPER(TRIM(w.work_order_status)) AS work_order_status,
  w.planned_qty,
  w.produced_qty,
  w.scrap_qty,
  w.produced_qty - w.scrap_qty AS good_qty,
  ROUND(CAST(w.scrap_qty AS NUMBER(18,4)) * 100 / NULLIF(w.produced_qty, 0), 1) AS scrap_rate_pct,
  ROUND(CAST(w.produced_qty AS NUMBER(18,4)) * 100 / NULLIF(w.planned_qty, 0), 1) AS attainment_pct,
  CAST(w.scrap_qty * pr.standard_cost AS NUMBER(18,2)) AS scrap_cost_aud,
  w.supervisor_employee_id,
  l.site_id,
  l.site_name,
  l.country,
  l.region
FROM production.bronze_work_orders w
JOIN production.silver_production_lines l ON l.line_id = w.line_id
JOIN production.silver_products pr ON pr.sku = w.sku;

-- silver_downtime_events: Downtime without duplicates, with planned flag,
-- line, site and region.

CREATE OR REPLACE TABLE production.silver_downtime_events
COMMENT = 'Downtime without duplicates, with planned flag, line, site and region.'
AS
WITH deduplicated AS (
  -- The MES re-sends some events: keep the latest copy of each.
  SELECT e.*, ROW_NUMBER() OVER (PARTITION BY e.event_id ORDER BY e._batch_id DESC) AS rn
  FROM production.bronze_downtime_events e
)
SELECT e.event_id, e.line_id, l.line_name, e.work_order_id, e.started_at, CAST(e.started_at AS DATE) AS event_date,
       e.duration_minutes, e.reason_code,
       CASE WHEN e.reason_code IN ('PLANNED_MAINTENANCE', 'CHANGEOVER') THEN TRUE ELSE FALSE END AS is_planned,
       e.operator_comment, e.reported_by_employee_id, l.site_id, l.site_name, l.country, l.region
FROM deduplicated e
JOIN production.silver_production_lines l ON l.line_id = e.line_id
WHERE e.rn = 1;

-- silver_safety_incidents: Safety incidents with month, lost time flag, site
-- and region.

CREATE OR REPLACE TABLE production.silver_safety_incidents
COMMENT = 'Safety incidents with month, lost time flag, site and region.'
AS
SELECT i.incident_id, i.site_id, si.site_name, i.occurred_at, CAST(i.occurred_at AS DATE) AS incident_date,
       CAST(DATE_TRUNC('MONTH', CAST(i.occurred_at AS DATE)) AS DATE) AS incident_month, i.incident_type, i.severity, i.injured_employee_id,
       i.injury_type, i.body_part, i.treatment, i.lost_time_days,
       CASE WHEN i.lost_time_days > 0 THEN TRUE ELSE FALSE END AS is_lost_time_injury, i.workers_comp_claim_number,
       i.description, i.reported_by_employee_id, si.country, si.region
FROM production.bronze_safety_incidents i
JOIN production.silver_sites si ON si.site_id = i.site_id;

-- ----------------------------------------------------------------------------
-- Gold: business-ready data products for reporting and AI. Built from silver.
-- ----------------------------------------------------------------------------

-- gold_line_performance_daily: Output by day and line: work orders, planned,
-- produced, good and scrap quantities, AUD scrap cost, downtime and
-- availability.

CREATE OR REPLACE TABLE production.gold_line_performance_daily
COMMENT = 'Output by day and line: work orders, planned, produced, good and scrap quantities, AUD scrap cost, downtime and availability.'
AS
WITH line_output AS (
  SELECT line_id, scheduled_date, COUNT(*) AS work_orders, SUM(planned_qty) AS planned_qty, SUM(produced_qty) AS produced_qty,
         SUM(good_qty) AS good_qty, SUM(scrap_qty) AS scrap_qty, SUM(scrap_cost_aud) AS scrap_cost_aud
  FROM production.silver_work_orders
  WHERE work_order_status IN ('COMPLETED', 'IN_PROGRESS')
  GROUP BY line_id, scheduled_date
),
stoppages AS (
  SELECT line_id, event_date, SUM(duration_minutes) AS downtime_minutes,
         SUM(CASE WHEN NOT is_planned THEN duration_minutes ELSE 0 END) AS unplanned_downtime_minutes
  FROM production.silver_downtime_events
  GROUP BY line_id, event_date
)
SELECT
  o.scheduled_date AS production_date,
  l.site_id,
  l.site_name,
  o.line_id,
  l.line_name,
  l.product_family,
  o.work_orders,
  o.planned_qty,
  o.produced_qty,
  o.good_qty,
  o.scrap_qty,
  ROUND(CAST(o.scrap_qty AS NUMBER(18,4)) * 100 / NULLIF(o.produced_qty, 0), 1) AS scrap_rate_pct,
  o.scrap_cost_aud,
  COALESCE(st.downtime_minutes, 0) AS downtime_minutes,
  COALESCE(st.unplanned_downtime_minutes, 0) AS unplanned_downtime_minutes,
  ROUND(CAST(GREATEST(l.scheduled_minutes_per_day - COALESCE(st.downtime_minutes, 0), 0) AS NUMBER(18,4)) * 100 / NULLIF(l.scheduled_minutes_per_day, 0), 1) AS availability_pct,
  l.country,
  l.region
FROM line_output o
JOIN production.silver_production_lines l ON l.line_id = o.line_id
LEFT JOIN stoppages st ON st.line_id = o.line_id AND st.event_date = o.scheduled_date;

-- gold_downtime_pareto: Downtime by month, line and reason: events, minutes
-- and the latest operator comment.

CREATE OR REPLACE TABLE production.gold_downtime_pareto
COMMENT = 'Downtime by month, line and reason: events, minutes and the latest operator comment.'
AS
WITH ranked AS (
  SELECT e.*, CAST(DATE_TRUNC('MONTH', e.event_date) AS DATE) AS event_month,
         ROW_NUMBER() OVER (PARTITION BY CAST(DATE_TRUNC('MONTH', e.event_date) AS DATE), e.line_id, e.reason_code ORDER BY e.started_at DESC) AS rn
  FROM production.silver_downtime_events e
)
SELECT
  event_month,
  site_name,
  line_id,
  line_name,
  reason_code,
  region,
  COUNT(*) AS events,
  SUM(duration_minutes) AS downtime_minutes,
  ROUND(AVG(duration_minutes), 1) AS avg_minutes_per_event,
  MAX(CASE WHEN rn = 1 THEN operator_comment END) AS latest_comment
FROM ranked
GROUP BY 1, 2, 3, 4, 5, 6;

-- gold_safety_summary: Safety incidents by month and site: injuries, lost time
-- injuries and days, near misses and workers compensation claims.

CREATE OR REPLACE TABLE production.gold_safety_summary
COMMENT = 'Safety incidents by month and site: injuries, lost time injuries and days, near misses and workers compensation claims.'
AS
SELECT
  incident_month,
  site_id,
  site_name,
  region,
  COUNT(*) AS incidents,
  SUM(CASE WHEN incident_type = 'INJURY' THEN 1 ELSE 0 END) AS injuries,
  SUM(CASE WHEN is_lost_time_injury THEN 1 ELSE 0 END) AS lost_time_injuries,
  SUM(lost_time_days) AS lost_time_days,
  SUM(CASE WHEN incident_type = 'NEAR_MISS' THEN 1 ELSE 0 END) AS near_misses,
  SUM(CASE WHEN severity = 'HIGH' THEN 1 ELSE 0 END) AS high_severity_incidents,
  SUM(CASE WHEN workers_comp_claim_number IS NOT NULL THEN 1 ELSE 0 END) AS workers_comp_claims
FROM production.silver_safety_incidents
GROUP BY 1, 2, 3, 4;

-- ============================================================================
-- Forgeline Supply Chain (supply_chain)
-- Supply chain: suppliers, purchase orders, customers, sales orders and
-- inventory. Source: the ERP.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Bronze: raw extracts from the source systems, loaded as-is.
-- ----------------------------------------------------------------------------

-- bronze_suppliers: Suppliers of castings, steel, electrical parts, bearings,
-- seals, packaging and freight, with bank details for payment.
