-- ----------------------------------------------------------------------------
-- Silver: cleaned, typed and conformed. Built from bronze.
-- ----------------------------------------------------------------------------

-- silver_suppliers: Suppliers with trimmed names, ABN digits only, ISO country
-- and region.

CREATE OR REPLACE TABLE supply_chain.silver_suppliers
COMMENT = 'Suppliers with trimmed names, ABN digits only, ISO country and region.'
AS
WITH base AS (
  SELECT
    su.supplier_id,
    TRIM(su.supplier_name) AS supplier_name,
    su.category,
    REGEXP_REPLACE(su.abn, '[^0-9]', '') AS abn,
    su.registration_number,
    su.city,
    CASE WHEN UPPER(TRIM(su.country)) IN ('AU', 'AUS', 'AUSTRALIA') THEN 'AU' WHEN UPPER(TRIM(su.country)) IN ('NZ', 'NZL', 'NEW ZEALAND') THEN 'NZ' WHEN UPPER(TRIM(su.country)) IN ('SG', 'SGP', 'SINGAPORE') THEN 'SG' WHEN UPPER(TRIM(su.country)) IN ('GB', 'GBR', 'UK', 'UNITED KINGDOM') THEN 'GB' WHEN UPPER(TRIM(su.country)) IN ('US', 'USA', 'UNITED STATES') THEN 'US' ELSE UPPER(TRIM(su.country)) END AS country,
    su.contact_name,
    LOWER(TRIM(su.contact_email)) AS contact_email,
    su.contact_phone,
    su.bank_bsb,
    su.bank_account_number,
    su.iban,
    su.payment_terms_days,
    su.is_preferred,
    su.onboarded_date
  FROM supply_chain.bronze_suppliers su
)
SELECT base.*, CASE WHEN base.country IN ('AU', 'NZ', 'SG', 'JP', 'IN', 'MY', 'ID', 'HK') THEN 'APAC' WHEN base.country IN ('GB', 'IE', 'DE', 'FR', 'NL', 'AE', 'ZA') THEN 'EMEA' WHEN base.country IN ('US', 'CA', 'MX', 'BR') THEN 'AMER' ELSE 'UNKNOWN' END AS region
FROM base;

-- silver_purchase_orders: Purchase orders with supplier, receiving site, AUD
-- amounts, days late and on-time flag. region is the receiving site's.

CREATE OR REPLACE TABLE supply_chain.silver_purchase_orders
COMMENT = 'Purchase orders with supplier, receiving site, AUD amounts, days late and on-time flag. region is the receiving site\'s.'
AS
WITH base AS (
  SELECT po.*, UPPER(TRIM(po.po_status)) AS clean_status
  FROM supply_chain.bronze_purchase_orders po
)
SELECT
  po.po_id,
  po.supplier_id,
  su.supplier_name,
  su.country AS supplier_country,
  po.site_id,
  si.site_name,
  po.material_description,
  po.category,
  po.quantity,
  po.unit_price,
  po.currency,
  CAST(po.quantity * po.unit_price AS NUMBER(18,2)) AS order_amount,
  CAST(po.quantity * po.unit_price * CASE po.currency WHEN 'AUD' THEN 1.00 WHEN 'NZD' THEN 0.92 WHEN 'SGD' THEN 1.13 WHEN 'GBP' THEN 1.95 WHEN 'USD' THEN 1.52 WHEN 'EUR' THEN 1.66 END AS NUMBER(18,2)) AS order_amount_aud,
  po.order_date,
  CAST(DATE_TRUNC('MONTH', po.order_date) AS DATE) AS order_month,
  po.promised_date,
  po.received_date,
  po.clean_status AS po_status,
  CASE WHEN po.clean_status = 'OPEN' THEN TRUE ELSE FALSE END AS is_open,
  CASE WHEN po.received_date IS NOT NULL THEN DATEDIFF(day, CAST(po.promised_date AS DATE), CAST(po.received_date AS DATE))
       WHEN po.clean_status = 'OPEN' AND po.promised_date < CURRENT_DATE THEN DATEDIFF(day, CAST(po.promised_date AS DATE), CAST(CURRENT_DATE AS DATE)) END AS days_late,
  CASE WHEN po.received_date IS NOT NULL AND po.received_date <= po.promised_date THEN TRUE ELSE FALSE END AS is_on_time,
  po.buyer_employee_id,
  si.country,
  si.region
FROM base po
JOIN supply_chain.silver_suppliers su ON su.supplier_id = po.supplier_id
JOIN production.silver_sites si ON si.site_id = po.site_id;

-- silver_customers: Customers with trimmed names, ABN digits only, ISO country
-- and region.

CREATE OR REPLACE TABLE supply_chain.silver_customers
COMMENT = 'Customers with trimmed names, ABN digits only, ISO country and region.'
AS
WITH base AS (
  SELECT
    c.customer_id,
    TRIM(c.company_name) AS customer_name,
    c.industry,
    REGEXP_REPLACE(c.abn, '[^0-9]', '') AS abn,
    c.registration_number,
    c.contact_first_name,
    c.contact_last_name,
    c.contact_title,
    LOWER(TRIM(c.contact_email)) AS contact_email,
    c.contact_phone,
    c.address_line,
    c.suburb,
    c.state,
    c.postcode,
    CASE WHEN UPPER(TRIM(c.country)) IN ('AU', 'AUS', 'AUSTRALIA') THEN 'AU' WHEN UPPER(TRIM(c.country)) IN ('NZ', 'NZL', 'NEW ZEALAND') THEN 'NZ' WHEN UPPER(TRIM(c.country)) IN ('SG', 'SGP', 'SINGAPORE') THEN 'SG' WHEN UPPER(TRIM(c.country)) IN ('GB', 'GBR', 'UK', 'UNITED KINGDOM') THEN 'GB' WHEN UPPER(TRIM(c.country)) IN ('US', 'USA', 'UNITED STATES') THEN 'US' ELSE UPPER(TRIM(c.country)) END AS country,
    c.credit_limit,
    c.payment_terms_days,
    c.account_manager_employee_id,
    c.customer_since
  FROM supply_chain.bronze_customers c
)
SELECT base.*, CASE WHEN base.country IN ('AU', 'NZ', 'SG', 'JP', 'IN', 'MY', 'ID', 'HK') THEN 'APAC' WHEN base.country IN ('GB', 'IE', 'DE', 'FR', 'NL', 'AE', 'ZA') THEN 'EMEA' WHEN base.country IN ('US', 'CA', 'MX', 'BR') THEN 'AMER' ELSE 'UNKNOWN' END AS region
FROM base;

-- silver_sales_orders: Sales orders with customer, product, discounted and AUD
-- amounts, on-time flag and the customer's region.

CREATE OR REPLACE TABLE supply_chain.silver_sales_orders
COMMENT = 'Sales orders with customer, product, discounted and AUD amounts, on-time flag and the customer\'s region.'
AS
SELECT
  so.order_id,
  so.customer_id,
  c.customer_name,
  c.industry,
  so.sku,
  pr.product_name,
  pr.product_family,
  so.quantity,
  so.unit_price,
  so.discount_pct,
  so.currency,
  CAST(so.quantity * so.unit_price * (100 - so.discount_pct) / 100 AS NUMBER(18,2)) AS order_amount,
  CAST(so.quantity * so.unit_price * (100 - so.discount_pct) / 100 * CASE so.currency WHEN 'AUD' THEN 1.00 WHEN 'NZD' THEN 0.92 WHEN 'SGD' THEN 1.13 WHEN 'GBP' THEN 1.95 WHEN 'USD' THEN 1.52 WHEN 'EUR' THEN 1.66 END AS NUMBER(18,2)) AS order_amount_aud,
  so.order_date,
  CAST(DATE_TRUNC('MONTH', so.order_date) AS DATE) AS order_month,
  so.requested_date,
  so.shipped_date,
  so.delivered_date,
  so.order_status,
  CASE WHEN so.delivered_date IS NOT NULL AND so.delivered_date <= so.requested_date THEN TRUE ELSE FALSE END AS is_on_time,
  CASE WHEN so.delivered_date IS NOT NULL THEN GREATEST(DATEDIFF(day, CAST(so.requested_date AS DATE), CAST(so.delivered_date AS DATE)), 0) END AS days_late,
  so.ship_from_site_id,
  si.site_name AS ship_from_site_name,
  so.carrier,
  so.customer_po_number,
  c.country,
  c.region
FROM supply_chain.bronze_sales_orders so
JOIN supply_chain.silver_customers c ON c.customer_id = so.customer_id
JOIN production.silver_products pr ON pr.sku = so.sku
JOIN production.silver_sites si ON si.site_id = so.ship_from_site_id;

-- silver_inventory: Stock by product and site with available quantity, stock
-- status and AUD stock value.

CREATE OR REPLACE TABLE supply_chain.silver_inventory
COMMENT = 'Stock by product and site with available quantity, stock status and AUD stock value.'
AS
SELECT
  i.snapshot_date,
  i.sku,
  pr.product_name,
  pr.product_family,
  i.site_id,
  si.site_name,
  si.site_type,
  i.on_hand_qty,
  i.allocated_qty,
  i.on_hand_qty - i.allocated_qty AS available_qty,
  i.reorder_point,
  i.safety_stock,
  CASE WHEN i.on_hand_qty < i.safety_stock THEN 'BELOW_SAFETY_STOCK'
       WHEN i.on_hand_qty <= i.reorder_point THEN 'BELOW_REORDER_POINT' ELSE 'OK' END AS stock_status,
  CAST(i.on_hand_qty * pr.standard_cost AS NUMBER(18,2)) AS stock_value_aud,
  i.last_counted_date,
  si.country,
  si.region
FROM supply_chain.bronze_inventory i
JOIN production.silver_products pr ON pr.sku = i.sku
JOIN production.silver_sites si ON si.site_id = i.site_id;

-- ----------------------------------------------------------------------------
-- Gold: business-ready data products for reporting and AI. Built from silver.
-- ----------------------------------------------------------------------------

-- gold_supplier_performance: One row per supplier: purchase orders and AUD
-- spend in the last six months, on-time delivery and open and overdue orders.

CREATE OR REPLACE TABLE supply_chain.gold_supplier_performance
COMMENT = 'One row per supplier: purchase orders and AUD spend in the last six months, on-time delivery and open and overdue orders.'
AS
WITH orders AS (
  SELECT
    supplier_id,
    COUNT(*) AS purchase_orders_6_months,
    SUM(order_amount_aud) AS spend_6_months_aud,
    SUM(CASE WHEN received_date IS NOT NULL THEN 1 ELSE 0 END) AS received_orders,
    SUM(CASE WHEN is_on_time THEN 1 ELSE 0 END) AS on_time_orders,
    ROUND(AVG(CASE WHEN days_late > 0 THEN days_late END), 1) AS avg_days_late_when_late,
    SUM(CASE WHEN is_open THEN 1 ELSE 0 END) AS open_orders,
    SUM(CASE WHEN is_open AND days_late > 0 THEN 1 ELSE 0 END) AS overdue_open_orders
  FROM supply_chain.silver_purchase_orders
  WHERE order_date >= DATEADD(day, -183, CURRENT_DATE) AND po_status <> 'CANCELLED'
  GROUP BY supplier_id
)
SELECT
  su.supplier_id,
  su.supplier_name,
  su.category,
  su.is_preferred,
  COALESCE(o.purchase_orders_6_months, 0) AS purchase_orders_6_months,
  COALESCE(o.spend_6_months_aud, 0) AS spend_6_months_aud,
  COALESCE(o.received_orders, 0) AS received_orders,
  ROUND(CAST(o.on_time_orders AS NUMBER(18,4)) * 100 / NULLIF(o.received_orders, 0), 1) AS on_time_pct,
  o.avg_days_late_when_late,
  COALESCE(o.open_orders, 0) AS open_orders,
  COALESCE(o.overdue_open_orders, 0) AS overdue_open_orders,
  su.country,
  su.region
FROM supply_chain.silver_suppliers su
LEFT JOIN orders o ON o.supplier_id = su.supplier_id;

-- gold_sales_daily: Sales orders by day, product family and customer region:
-- orders, customers, units and AUD revenue.

CREATE OR REPLACE TABLE supply_chain.gold_sales_daily
COMMENT = 'Sales orders by day, product family and customer region: orders, customers, units and AUD revenue.'
AS
SELECT
  order_date,
  product_family,
  region,
  COUNT(*) AS orders,
  COUNT(DISTINCT customer_id) AS customers,
  SUM(quantity) AS units,
  SUM(order_amount_aud) AS revenue_aud,
  SUM(CASE WHEN order_status IN ('OPEN', 'SHIPPED') THEN 1 ELSE 0 END) AS orders_not_yet_delivered
FROM supply_chain.silver_sales_orders
WHERE order_status <> 'CANCELLED'
GROUP BY 1, 2, 3;

-- gold_inventory_position: Stock by product and site with stock status, open
-- order demand, units shipped in 90 days and days of cover.

CREATE OR REPLACE TABLE supply_chain.gold_inventory_position
COMMENT = 'Stock by product and site with stock status, open order demand, units shipped in 90 days and days of cover.'
AS
WITH demand AS (
  SELECT
    sku,
    ship_from_site_id AS site_id,
    SUM(CASE WHEN order_status = 'OPEN' THEN quantity ELSE 0 END) AS open_order_qty,
    SUM(CASE WHEN shipped_date >= DATEADD(day, -90, CURRENT_DATE) THEN quantity ELSE 0 END) AS shipped_90_days_qty
  FROM supply_chain.silver_sales_orders
  GROUP BY sku, ship_from_site_id
)
SELECT
  i.sku,
  i.product_name,
  i.product_family,
  i.site_id,
  i.site_name,
  i.on_hand_qty,
  i.allocated_qty,
  i.available_qty,
  i.reorder_point,
  i.safety_stock,
  i.stock_status,
  i.stock_value_aud,
  COALESCE(dm.open_order_qty, 0) AS open_order_qty,
  COALESCE(dm.shipped_90_days_qty, 0) AS shipped_90_days_qty,
  ROUND(CAST(i.available_qty AS DECIMAL(12,1)) * 90 / NULLIF(dm.shipped_90_days_qty, 0), 1) AS days_of_cover,
  i.country,
  i.region
FROM supply_chain.silver_inventory i
LEFT JOIN demand dm ON dm.sku = i.sku AND dm.site_id = i.site_id;

-- ============================================================================
-- Forgeline Quality (quality)
-- Quality: inspections, defects, non-conformance reports, customer complaints
-- and warranty claims. Source: the quality management system (QMS).
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Bronze: raw extracts from the source systems, loaded as-is.
-- ----------------------------------------------------------------------------

-- bronze_inspections: Final and first article inspections of completed work
-- orders. result is entered by hand: PASS, Pass, pass...
--   Columns of note:
--     inspector_employee_id: Matches employee_id in the HR data
--   Rows: 600

CREATE OR REPLACE TABLE quality.bronze_inspections (
  inspection_id VARCHAR,
  work_order_id VARCHAR,
  sku VARCHAR,
  inspected_at TIMESTAMP_NTZ,
  inspection_type VARCHAR,
  sample_size INT,
  defects_found INT,
  result VARCHAR,
  inspector_employee_id VARCHAR COMMENT 'Matches employee_id in the HR data',
  _source_system VARCHAR,
  _batch_id VARCHAR
)
COMMENT = 'Final and first article inspections of completed work orders. result is entered by hand: PASS, Pass, pass...';


-- bronze_defects: Defects found at inspection, with severity and what was done
-- with the units.
--   Columns of note:
--     disposition: USE_AS_IS, REWORK or SCRAP
--     notes: Free text: inspector names
--   Rows: 112

CREATE OR REPLACE TABLE quality.bronze_defects (
  defect_id VARCHAR,
  inspection_id VARCHAR,
  defect_type VARCHAR,
  severity VARCHAR,
  quantity INT,
  disposition VARCHAR COMMENT 'USE_AS_IS, REWORK or SCRAP',
  notes VARCHAR COMMENT 'Free text: inspector names',
  _source_system VARCHAR,
  _batch_id VARCHAR
)
COMMENT = 'Defects found at inspection, with severity and what was done with the units.';


-- bronze_non_conformances: Non-conformance reports raised from inspections,
-- supplier deliveries and customer complaints.
--   Columns of note:
--     ncr_source: INTERNAL, SUPPLIER or CUSTOMER
--     cost_of_quality_aud: Rework, scrap and containment cost
--     owner_employee_id: Matches employee_id in the HR data
--   Rows: 100

CREATE OR REPLACE TABLE quality.bronze_non_conformances (
  ncr_id VARCHAR,
  raised_date DATE,
  ncr_source VARCHAR COMMENT 'INTERNAL, SUPPLIER or CUSTOMER',
  site_id VARCHAR,
  sku VARCHAR,
  work_order_id VARCHAR,
  supplier_id VARCHAR,
  complaint_id VARCHAR,
  description VARCHAR,
  root_cause_category VARCHAR,
  ncr_status VARCHAR,
  closed_date DATE,
  cost_of_quality_aud NUMBER(12,2) COMMENT 'Rework, scrap and containment cost',
  corrective_action VARCHAR,
  owner_employee_id VARCHAR COMMENT 'Matches employee_id in the HR data',
  _source_system VARCHAR,
  _batch_id VARCHAR
)
COMMENT = 'Non-conformance reports raised from inspections, supplier deliveries and customer complaints.';


-- bronze_customer_complaints: Customer complaints about products, deliveries,
-- safety, service and billing.
--   Columns of note:
--     contact_name: Person name
--     contact_email: PII: email
--     contact_phone: PII: phone number
--     complaint_text: Free text: names, phone numbers, emails, addresses
--       and injuries to customer staff
--     assigned_employee_id: Matches employee_id in the HR data
--   Rows: 110

CREATE OR REPLACE TABLE quality.bronze_customer_complaints (
  complaint_id VARCHAR,
  customer_id VARCHAR,
  order_id VARCHAR,
  sku VARCHAR,
  received_at TIMESTAMP_NTZ,
  channel VARCHAR,
  category VARCHAR,
  severity VARCHAR,
  contact_name VARCHAR COMMENT 'Person name',
  contact_email VARCHAR COMMENT 'PII: email',
  contact_phone VARCHAR COMMENT 'PII: phone number',
  complaint_text VARCHAR COMMENT 'Free text: names, phone numbers, emails, addresses and injuries to customer staff',
  complaint_status VARCHAR,
  closed_date DATE,
  assigned_employee_id VARCHAR COMMENT 'Matches employee_id in the HR data',
  _source_system VARCHAR,
  _batch_id VARCHAR
)
COMMENT = 'Customer complaints about products, deliveries, safety, service and billing.';


-- bronze_warranty_claims: Warranty claims on delivered products.
-- approved_amount is empty while a claim is pending.
--   Rows: 130

CREATE OR REPLACE TABLE quality.bronze_warranty_claims (
  claim_id VARCHAR,
  customer_id VARCHAR,
  order_id VARCHAR,
  sku VARCHAR,
  serial_number VARCHAR,
  claim_date DATE,
  failure_mode VARCHAR,
  failure_description VARCHAR,
  claimed_amount NUMBER(12,2),
  approved_amount NUMBER(12,2),
  currency VARCHAR,
  claim_status VARCHAR,
  _source_system VARCHAR,
  _batch_id VARCHAR
)
COMMENT = 'Warranty claims on delivered products. approved_amount is empty while a claim is pending.';


-- ----------------------------------------------------------------------------
-- Silver: cleaned, typed and conformed. Built from bronze.
-- ----------------------------------------------------------------------------

-- silver_inspections: Inspections with clean result, pass flag, defect rate,
-- product, line and the site's region.

CREATE OR REPLACE TABLE quality.silver_inspections
COMMENT = 'Inspections with clean result, pass flag, defect rate, product, line and the site\'s region.'
AS
WITH base AS (
  SELECT i.*, UPPER(TRIM(i.result)) AS clean_result
  FROM quality.bronze_inspections i
)
SELECT
  i.inspection_id,
  i.work_order_id,
  i.sku,
  w.product_name,
  w.product_family,
  i.inspected_at,
  CAST(i.inspected_at AS DATE) AS inspection_date,
  CAST(DATE_TRUNC('MONTH', CAST(i.inspected_at AS DATE)) AS DATE) AS inspection_month,
  i.inspection_type,
  i.sample_size,
  i.defects_found,
  ROUND(CAST(i.defects_found AS NUMBER(18,4)) * 100 / NULLIF(i.sample_size, 0), 1) AS defect_rate_pct,
  i.clean_result AS result,
  CASE WHEN i.clean_result = 'PASS' THEN TRUE ELSE FALSE END AS is_pass,
  i.inspector_employee_id,
  w.line_id,
  w.line_name,
  w.site_id,
  w.site_name,
  w.country,
  w.region
FROM base i
JOIN production.silver_work_orders w ON w.work_order_id = i.work_order_id;

-- silver_defects: Defects with the inspection's product, line, site and
-- region.

CREATE OR REPLACE TABLE quality.silver_defects
COMMENT = 'Defects with the inspection\'s product, line, site and region.'
AS
SELECT df.defect_id, df.inspection_id, i.work_order_id, i.sku, i.product_family, i.inspection_date, df.defect_type, df.severity,
       df.quantity, df.disposition, df.notes, i.line_id, i.site_id, i.country, i.region
FROM quality.bronze_defects df
JOIN quality.silver_inspections i ON i.inspection_id = df.inspection_id;

-- silver_non_conformances: Non-conformance reports with product, open flag,
-- days open and the site's region.

CREATE OR REPLACE TABLE quality.silver_non_conformances
COMMENT = 'Non-conformance reports with product, open flag, days open and the site\'s region.'
AS
SELECT
  ncr.ncr_id,
  ncr.raised_date,
  CAST(DATE_TRUNC('MONTH', ncr.raised_date) AS DATE) AS raised_month,
  ncr.ncr_source,
  ncr.site_id,
  si.site_name,
  ncr.sku,
  pr.product_name,
  pr.product_family,
  ncr.work_order_id,
  ncr.supplier_id,
  ncr.complaint_id,
  ncr.description,
  ncr.root_cause_category,
  ncr.ncr_status,
  CASE WHEN ncr.ncr_status = 'CLOSED' THEN FALSE ELSE TRUE END AS is_open,
  ncr.closed_date,
  DATEDIFF(day, CAST(ncr.raised_date AS DATE), CAST(COALESCE(ncr.closed_date, CURRENT_DATE) AS DATE)) AS days_open,
  ncr.cost_of_quality_aud,
  ncr.corrective_action,
  ncr.owner_employee_id,
  si.country,
  si.region
FROM quality.bronze_non_conformances ncr
JOIN production.silver_sites si ON si.site_id = ncr.site_id
JOIN production.silver_products pr ON pr.sku = ncr.sku;

-- silver_customer_complaints: Complaints with customer, product, open flag,
-- days open and the customer's region.

CREATE OR REPLACE TABLE quality.silver_customer_complaints
COMMENT = 'Complaints with customer, product, open flag, days open and the customer\'s region.'
AS
SELECT
  cc.complaint_id,
  cc.customer_id,
  c.customer_name,
  c.industry,
  cc.order_id,
  cc.sku,
  pr.product_name,
  pr.product_family,
  cc.received_at,
  CAST(cc.received_at AS DATE) AS received_date,
  cc.channel,
  cc.category,
  cc.severity,
  cc.contact_name,
  LOWER(TRIM(cc.contact_email)) AS contact_email,
  cc.contact_phone,
  cc.complaint_text,
  cc.complaint_status,
  CASE WHEN cc.complaint_status IN ('OPEN', 'IN_PROGRESS') THEN TRUE ELSE FALSE END AS is_open,
  cc.closed_date,
  DATEDIFF(day, CAST(cc.received_at AS DATE), CAST(COALESCE(cc.closed_date, CURRENT_DATE) AS DATE)) AS days_open,
  cc.assigned_employee_id,
  c.country,
  c.region
FROM quality.bronze_customer_complaints cc
JOIN supply_chain.silver_customers c ON c.customer_id = cc.customer_id
JOIN production.silver_products pr ON pr.sku = cc.sku;

-- silver_warranty_claims: Warranty claims with customer, product, days after
-- delivery, AUD amounts and the customer's region.

CREATE OR REPLACE TABLE quality.silver_warranty_claims
COMMENT = 'Warranty claims with customer, product, days after delivery, AUD amounts and the customer\'s region.'
AS
SELECT
  wc.claim_id,
  wc.customer_id,
  so.customer_name,
  wc.order_id,
  wc.sku,
  so.product_name,
  so.product_family,
  wc.serial_number,
  wc.claim_date,
  CAST(DATE_TRUNC('MONTH', wc.claim_date) AS DATE) AS claim_month,
  DATEDIFF(day, CAST(so.delivered_date AS DATE), CAST(wc.claim_date AS DATE)) AS days_after_delivery,
  wc.failure_mode,
  wc.failure_description,
  wc.claimed_amount,
  wc.approved_amount,
  wc.currency,
  CAST(wc.claimed_amount * CASE wc.currency WHEN 'AUD' THEN 1.00 WHEN 'NZD' THEN 0.92 WHEN 'SGD' THEN 1.13 WHEN 'GBP' THEN 1.95 WHEN 'USD' THEN 1.52 WHEN 'EUR' THEN 1.66 END AS NUMBER(18,2)) AS claimed_amount_aud,
  CAST(wc.approved_amount * CASE wc.currency WHEN 'AUD' THEN 1.00 WHEN 'NZD' THEN 0.92 WHEN 'SGD' THEN 1.13 WHEN 'GBP' THEN 1.95 WHEN 'USD' THEN 1.52 WHEN 'EUR' THEN 1.66 END AS NUMBER(18,2)) AS approved_amount_aud,
  wc.claim_status,
  so.ship_from_site_id,
  so.country,
  so.region
FROM quality.bronze_warranty_claims wc
JOIN supply_chain.silver_sales_orders so ON so.order_id = wc.order_id;

-- ----------------------------------------------------------------------------
-- Gold: business-ready data products for reporting and AI. Built from silver.
-- ----------------------------------------------------------------------------

-- gold_first_pass_yield: Inspections by month, site, line and product family:
-- first pass yield and defects per 100 units inspected.

CREATE OR REPLACE TABLE quality.gold_first_pass_yield
COMMENT = 'Inspections by month, site, line and product family: first pass yield and defects per 100 units inspected.'
AS
SELECT
  inspection_month,
  site_id,
  site_name,
  line_id,
  line_name,
  product_family,
  region,
  COUNT(*) AS inspections,
  SUM(CASE WHEN is_pass THEN 1 ELSE 0 END) AS passed,
  ROUND(CAST(SUM(CASE WHEN is_pass THEN 1 ELSE 0 END) AS NUMBER(18,4)) * 100 / NULLIF(COUNT(*), 0), 1) AS first_pass_yield_pct,
  SUM(sample_size) AS units_inspected,
  SUM(defects_found) AS defects_found,
  ROUND(CAST(SUM(defects_found) AS NUMBER(18,4)) * 100 / NULLIF(SUM(sample_size), 0), 1) AS defects_per_100_units
FROM quality.silver_inspections
GROUP BY 1, 2, 3, 4, 5, 6, 7;

-- gold_complaint_overview: One row per complaint: customer and contact,
-- product, severity, status, days open, related warranty claims and NCR, and
-- the complaint text.

CREATE OR REPLACE TABLE quality.gold_complaint_overview
COMMENT = 'One row per complaint: customer and contact, product, severity, status, days open, related warranty claims and NCR, and the complaint text.'
AS
WITH warranty AS (
  SELECT order_id, COUNT(*) AS warranty_claims, SUM(approved_amount_aud) AS warranty_approved_aud
  FROM quality.silver_warranty_claims
  GROUP BY order_id
),
ncrs AS (
  SELECT complaint_id, MIN(ncr_id) AS ncr_id FROM quality.silver_non_conformances WHERE complaint_id IS NOT NULL GROUP BY complaint_id
)
SELECT
  cc.complaint_id,
  cc.received_date,
  cc.customer_id,
  cc.customer_name,
  cc.industry,
  cc.contact_name,
  cc.contact_email,
  cc.contact_phone,
  cc.order_id,
  cc.sku,
  cc.product_name,
  cc.product_family,
  cc.category,
  cc.severity,
  cc.complaint_status,
  cc.is_open,
  cc.days_open,
  COALESCE(wa.warranty_claims, 0) AS warranty_claims_on_order,
  COALESCE(wa.warranty_approved_aud, 0) AS warranty_approved_aud,
  n.ncr_id,
  cc.complaint_text,
  cc.assigned_employee_id,
  cc.country,
  cc.region
FROM quality.silver_customer_complaints cc
LEFT JOIN warranty wa ON wa.order_id = cc.order_id
LEFT JOIN ncrs n ON n.complaint_id = cc.complaint_id;

-- gold_cost_of_quality: Cost of quality by month and site in AUD: scrap from
-- production, non-conformances and approved warranty claims.

CREATE OR REPLACE TABLE quality.gold_cost_of_quality
COMMENT = 'Cost of quality by month and site in AUD: scrap from production, non-conformances and approved warranty claims.'
AS
WITH costs AS (
  SELECT CAST(DATE_TRUNC('MONTH', scheduled_date) AS DATE) AS cost_month, site_id, scrap_cost_aud, 0 AS ncr_cost_aud, 0 AS warranty_cost_aud
  FROM production.silver_work_orders
  WHERE work_order_status IN ('COMPLETED', 'IN_PROGRESS')
  UNION ALL
  SELECT raised_month, site_id, 0, cost_of_quality_aud, 0
  FROM quality.silver_non_conformances
  UNION ALL
  SELECT claim_month, ship_from_site_id, 0, 0, COALESCE(approved_amount_aud, 0)
  FROM quality.silver_warranty_claims
)
SELECT
  c.cost_month,
  c.site_id,
  si.site_name,
  si.region,
  SUM(c.scrap_cost_aud) AS scrap_cost_aud,
  SUM(c.ncr_cost_aud) AS ncr_cost_aud,
  SUM(c.warranty_cost_aud) AS warranty_cost_aud,
  SUM(c.scrap_cost_aud + c.ncr_cost_aud + c.warranty_cost_aud) AS total_cost_of_quality_aud
FROM costs c
JOIN production.silver_sites si ON si.site_id = c.site_id
GROUP BY 1, 2, 3, 4;
